import { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Card, CardContent } from "@/components/ui/card";
import { apiRequest } from "@/lib/queryClient";
import { useAuth } from "@/hooks/useAuth";

interface ChatInterfaceProps {
  conversation: any;
}

export default function ChatInterface({ conversation }: ChatInterfaceProps) {
  const [newMessage, setNewMessage] = useState("");
  const { user } = useAuth();
  const queryClient = useQueryClient();

  const { data: messages = [] } = useQuery({
    queryKey: ["/api/conversations", conversation.id, "messages"],
    enabled: !!conversation.id,
  });

  // Type guard per i messaggi
  const typedMessages = Array.isArray(messages) ? messages : [];

  const sendMessageMutation = useMutation({
    mutationFn: async (content: string) => {
      return apiRequest("POST", `/api/conversations/${conversation.id}/messages`, {
        content,
      });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ 
        queryKey: ["/api/conversations", conversation.id, "messages"] 
      });
      setNewMessage("");
    },
  });

  const handleSendMessage = () => {
    if (newMessage.trim()) {
      sendMessageMutation.mutate(newMessage.trim());
    }
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSendMessage();
    }
  };

  return (
    <>
      {/* Chat Header */}
      <div className="p-4 border-b border-slate-200 bg-slate-50">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <img 
              className="w-8 h-8 rounded-full object-cover bg-slate-200" 
              src="https://images.unsplash.com/photo-1560250097-0b93528c311a?ixlib=rb-4.0.3&auto=format&fit=crop&w=32&h=32" 
              alt="TechStore Milano"
            />
            <div>
              <h4 className="font-medium text-slate-900">TechStore Milano</h4>
              <p className="text-xs text-slate-500">iPhone 13 Pro 256GB Grafite</p>
            </div>
          </div>
          <div className="flex items-center gap-2">
            <button className="p-2 text-slate-400 hover:text-slate-600">
              <i className="fas fa-phone"></i>
            </button>
            <button className="p-2 text-slate-400 hover:text-slate-600">
              <i className="fas fa-video"></i>
            </button>
            <button className="p-2 text-slate-400 hover:text-slate-600">
              <i className="fas fa-ellipsis-v"></i>
            </button>
          </div>
        </div>
      </div>

      {/* Chat Messages */}
      <div className="flex-1 overflow-y-auto p-4 space-y-4">
        {typedMessages.length === 0 ? (
          <div className="text-center py-8">
            <div className="p-4 bg-slate-50 rounded-xl inline-flex items-center justify-center mb-4">
              <i className="fas fa-comments text-slate-400 text-2xl"></i>
            </div>
            <p className="text-slate-500">Nessun messaggio ancora. Inizia la conversazione!</p>
          </div>
        ) : (
          typedMessages.map((message: any) => (
            <div key={message.id} className={`flex gap-3 ${
              message.senderId === user?.id ? 'justify-end' : ''
            }`}>
              {message.senderId !== user?.id && (
                <img 
                  className="w-8 h-8 rounded-full object-cover bg-slate-200" 
                  src="https://images.unsplash.com/photo-1560250097-0b93528c311a?ixlib=rb-4.0.3&auto=format&fit=crop&w=32&h=32" 
                  alt="Contatto"
                />
              )}
              <div className={`flex-1 ${message.senderId === user?.id ? 'flex justify-end' : ''}`}>
                <div className={`rounded-xl p-3 max-w-sm ${
                  message.senderId === user?.id 
                    ? 'bg-primary text-white' 
                    : 'bg-slate-100 text-slate-900'
                }`}>
                  {message.messageType === 'offer' ? (
                    <div className="bg-gradient-to-r from-accent to-orange-400 rounded-xl p-4">
                      <div className="bg-white rounded-lg p-4">
                        <div className="flex items-center gap-2 mb-3">
                          <i className="fas fa-handshake text-accent"></i>
                          <span className="font-semibold text-slate-900">Offerta Formale</span>
                        </div>
                        <div className="space-y-2">
                          <div className="flex justify-between">
                            <span className="text-sm text-slate-600">Prodotto:</span>
                            <span className="text-sm font-medium">iPhone 13 Pro 256GB Grafite</span>
                          </div>
                          <div className="flex justify-between">
                            <span className="text-sm text-slate-600">Condizioni:</span>
                            <span className="text-sm font-medium">Eccellenti (9/10)</span>
                          </div>
                          <div className="flex justify-between">
                            <span className="text-sm text-slate-600">Prezzo:</span>
                            <span className="text-lg font-bold text-accent">€720</span>
                          </div>
                          <div className="flex justify-between">
                            <span className="text-sm text-slate-600">Garanzia:</span>
                            <span className="text-sm font-medium">6 mesi</span>
                          </div>
                        </div>
                        <div className="flex gap-2 mt-4">
                          <Button className="flex-1 bg-secondary hover:bg-secondary/90 text-sm">
                            <i className="fas fa-check mr-1"></i>
                            Accetta
                          </Button>
                          <Button variant="outline" className="flex-1 text-sm">
                            <i className="fas fa-comment mr-1"></i>
                            Negozia
                          </Button>
                        </div>
                      </div>
                    </div>
                  ) : (
                    <p className="text-sm">{message.content}</p>
                  )}
                </div>
              </div>
              {message.senderId === user?.id && (
                <img 
                  className="w-8 h-8 rounded-full object-cover bg-slate-200" 
                  src={user?.profileImageUrl || "https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?ixlib=rb-4.0.3&auto=format&fit=crop&w=32&h=32"} 
                  alt="Tu"
                />
              )}
            </div>
          ))
        )}
      </div>

      {/* Chat Input */}
      <div className="p-4 border-t border-slate-200">
        <div className="flex gap-2">
          <button className="p-2 text-slate-400 hover:text-slate-600">
            <i className="fas fa-paperclip"></i>
          </button>
          <Input
            value={newMessage}
            onChange={(e) => setNewMessage(e.target.value)}
            onKeyPress={handleKeyPress}
            placeholder="Scrivi un messaggio..."
            className="flex-1"
          />
          <Button 
            onClick={handleSendMessage}
            disabled={sendMessageMutation.isPending || !newMessage.trim()}
            className="bg-primary hover:bg-primary/90"
          >
            <i className="fas fa-paper-plane"></i>
          </Button>
        </div>
      </div>
    </>
  );
}

client/src/components/clemente-chat.tsx.content:
import { useState, useRef, useEffect } from "react";
import { useMutation } from "@tanstack/react-query";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { apiRequest } from "@/lib/queryClient";
import { ObjectUploader } from "./ObjectUploader";
import { VoiceRecorder } from "./VoiceRecorder";

interface ClementeChatProps {
  onDataUpdate: (data: any) => void;
}

interface Message {
  id: number;
  content: string;
  isAI: boolean;
  timestamp: Date;
  fileUrl?: string;
  fileName?: string;
  fileType?: 'image' | 'document' | 'other';
  aiGeneratedImage?: string;
}

export default function ClementeChat({ onDataUpdate }: ClementeChatProps) {
  const [messages, setMessages] = useState<Message[]>([
    {
      id: 1,
      content: "Ciao! Sono Clemente, il tuo assistente per trovare quello che cerchi. Cosa vorresti acquistare oggi?",
      isAI: true,
      timestamp: new Date(),
    },
  ]);
  const [newMessage, setNewMessage] = useState("");
  const [chatContext, setChatContext] = useState({});
  const messagesEndRef = useRef<HTMLDivElement>(null);

  // Auto-scroll quando arrivano nuovi messaggi
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const chatMutation = useMutation({
    mutationFn: async ({ message, attachedFile }: { message: string, attachedFile?: { url: string, name: string, type: string } }) => {
      return apiRequest("POST", "/api/clemente/chat", {
        message,
        context: {
          ...chatContext,
          conversationHistory: messages
        },
        attachedFile
      });
    },
    onSuccess: (data: any) => {
      // Add AI response to messages
      setMessages(prev => [...prev, {
        id: Date.now() + 1,
        content: typeof data.response === 'string' ? data.response : data.response.text,
        isAI: true,
        timestamp: new Date(),
        aiGeneratedImage: typeof data.response === 'object' ? data.response.generatedImage : undefined
      }]);

      // Update context and extracted data
      setChatContext(prev => ({ ...prev, ...data.extractedData }));
      onDataUpdate(data.extractedData);
    },
  });

  const handleSendMessage = () => {
    if (!newMessage.trim()) return;

    // Add user message
    const userMessage = {
      id: Date.now(),
      content: newMessage.trim(),
      isAI: false,
      timestamp: new Date(),
    };

    setMessages(prev => [...prev, userMessage]);

    // Send to AI
    chatMutation.mutate({ message: newMessage.trim() });
    setNewMessage("");
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSendMessage();
    }
  };

  const suggestedReplies = ["256GB", "€600-750", "Grafite", "Milano"];

  return (
    <>
      <div className="p-4 bg-slate-50 border-b border-slate-200">
        <div className="flex items-center gap-3">
          <div className="w-8 h-8 bg-green-100 rounded-full flex items-center justify-center p-1">
            <img 
              src="/attached_assets/Clemente foto profilo_1754847201275.png" 
              alt="Clemente AI" 
              className="w-full h-full object-contain"
            />
          </div>
          <div>
            <h3 className="font-medium text-slate-900">Clemente</h3>
            <p className="text-xs text-slate-500">Il tuo assistente AI</p>
          </div>
          <div className="ml-auto">
            <span className="inline-flex items-center px-2 py-1 rounded-full text-xs bg-green-100 text-green-800">
              <i className="fas fa-circle text-green-500 text-xs mr-1"></i>
              Online
            </span>
          </div>
        </div>
      </div>

      {/* Chat Messages */}
      <div className="h-96 overflow-y-auto p-4 space-y-4">
        {messages.map((message) => (
          <div key={message.id} className={`flex gap-3 ${message.isAI ? '' : 'justify-end'}`}>
            {message.isAI && (
              <div className="w-8 h-8 bg-green-100 rounded-full flex items-center justify-center flex-shrink-0 p-1">
                <img 
                  src="/attached_assets/Clemente foto profilo_1754847201275.png" 
                  alt="Clemente AI" 
                  className="w-full h-full object-contain"
                />
              </div>
            )}
            <div className={`flex-1 ${message.isAI ? '' : 'flex justify-end'}`}>
              <div className={`rounded-xl p-3 max-w-sm ${
                message.isAI ? 'bg-slate-100' : 'bg-primary text-white'
              }`}>
                <p className={`text-sm ${message.isAI ? 'text-slate-900' : 'text-white'}`}>
                  {message.content}
                </p>

                {/* Mostra file allegato dall'utente */}
                {message.fileUrl && (
                  <div className="mt-2 p-2 bg-white/20 rounded border">
                    {message.fileType === 'image' ? (
                      <img 
                        src={message.fileUrl} 
                        alt={message.fileName} 
                        className="max-w-full h-32 object-cover rounded"
                      />
                    ) : (
                      <div className="flex items-center gap-2">
                        <i className="fas fa-file"></i>
                        <span className="text-xs">{message.fileName}</span>
                      </div>
                    )}
                  </div>
                )}

                {/* Mostra immagine generata dall'AI */}
                {message.aiGeneratedImage && (
                  <div className="mt-2">
                    <img 
                      src={message.aiGeneratedImage} 
                      alt="Immagine di esempio generata da AI"
                      className="max-w-full h-40 object-cover rounded border"
                    />
                    <p className="text-xs opacity-70 mt-1">🎨 Immagine di esempio</p>
                  </div>
                )}
              </div>
              <p className="text-xs text-slate-500 mt-1">
                {message.timestamp.toLocaleTimeString('it-IT', { 
                  hour: '2-digit', 
                  minute: '2-digit' 
                })}
              </p>
            </div>
            {!message.isAI && (
              <div className="w-8 h-8 bg-slate-300 rounded-full flex items-center justify-center flex-shrink-0">
                <i className="fas fa-user text-slate-600 text-sm"></i>
              </div>
            )}
          </div>
        ))}

        {/* Typing Indicator */}
        {chatMutation.isPending && (
          <div className="flex gap-3">
            <div className="w-8 h-8 bg-primary rounded-full flex items-center justify-center flex-shrink-0">
🤖
            </div>
            <div className="flex-1">
              <div className="bg-slate-100 rounded-xl p-3 max-w-sm">
                <div className="flex space-x-1">
                  <div className="w-2 h-2 bg-slate-400 rounded-full animate-bounce"></div>
                  <div className="w-2 h-2 bg-slate-400 rounded-full animate-bounce" style={{ animationDelay: '0.1s' }}></div>
                  <div className="w-2 h-2 bg-slate-400 rounded-full animate-bounce" style={{ animationDelay: '0.2s' }}></div>
                </div>
              </div>
            </div>
          </div>
        )}

        {/* Elemento invisibile per l'auto-scroll */}
        <div ref={messagesEndRef} />
      </div>

      {/* Chat Input */}
      <div className="p-4 border-t border-slate-200">
        <div className="flex gap-2 items-end mb-2">
          <div className="flex-1">
            <Input
              value={newMessage}
              onChange={(e) => setNewMessage(e.target.value)}
              onKeyPress={handleKeyPress}
              placeholder="Scrivi un messaggio a Clemente..."
            />
          </div>

          {/* File Upload Button */}
          <ObjectUploader
            maxNumberOfFiles={5}
            maxFileSize={50485760}
            onGetUploadParameters={async () => {
              const response = await fetch('/api/objects/upload', {
                method: 'POST',
                credentials: 'include'
              });
              const data = await response.json();
              return { method: 'PUT' as const, url: data.uploadURL };
            }}
            onComplete={(result) => {
              result.successful?.forEach(file => {
                const fileName = file.name || 'File sconosciuto';
                const fileUrl = file.uploadURL || '';
                const fileType = (file.type || '').startsWith('image/') ? 'image' : 'document';

                setMessages(prev => [...prev, {
                  id: Date.now(),
                  content: `📎 File allegato: ${fileName}`,
                  isAI: false,
                  timestamp: new Date(),
                  fileUrl,
                  fileName,
                  fileType
                }]);

                // Send file info to AI with attachment data
                setTimeout(() => {
                  chatMutation.mutate({
                    message: `Ho allegato il file: ${fileName}. Puoi analizzarlo per aiutarmi con la richiesta?`,
                    attachedFile: { url: fileUrl, name: fileName, type: file.type || 'application/octet-stream' }
                  });
                }, 100);
              });
            }}
            buttonClassName="px-3 py-2 bg-slate-100 hover:bg-slate-200 border border-slate-300 rounded-md"
          >
📎
          </ObjectUploader>

          {/* Voice Recorder Button */}
          <VoiceRecorder
            onTranscription={(text) => {
              setNewMessage(text);
            }}
            onError={(error) => {
              console.error('Voice error:', error);
            }}
            className="px-3 py-2"
          />

          <Button 
            onClick={handleSendMessage}
            disabled={chatMutation.isPending || !newMessage.trim()}
            className="bg-primary hover:bg-primary/90 px-4"
          >
✈️
          </Button>
        </div>
        <div className="flex gap-2 mt-2">
          {suggestedReplies.map((reply) => (
            <button
              key={reply}
              onClick={() => {
                setNewMessage(reply);
                setTimeout(() => handleSendMessage(), 100);
              }}
              className="px-3 py-1 bg-slate-100 text-slate-700 rounded-full text-xs hover:bg-slate-200 transition-colors"
            >
              {reply}
            </button>
          ))}
        </div>
      </div>
    </>
  );
}

client/src/components/leonardo-chat.tsx.content:
import { useState, useRef, useEffect } from 'react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Textarea } from '@/components/ui/textarea';
import { Avatar, AvatarFallback } from '@/components/ui/avatar';
import { Mic, FileText, Send, Bot, User } from 'lucide-react';
import { useToast } from "@/hooks/use-toast";
import CharacterIntro from "@/components/character-intro";
import { useCharacterIntro } from "@/hooks/useCharacterIntro";

interface Message {
  id: string;
  sender: 'user' | 'leonardo';
  content: string;
  timestamp: Date;
}

interface LeonardoChatProps {
  context?: any;
  sessionId?: string;
}

export default function LeonardoChat({ context = {}, sessionId }: LeonardoChatProps) {
  const [messages, setMessages] = useState<Message[]>([
    {
      id: '1',
      sender: 'leonardo',
      content: 'Ciao! Sono Leonardo, il tuo assistente per vendere meglio. Come posso aiutarti oggi?',
      timestamp: new Date()
    }
  ]);
  const [inputMessage, setInputMessage] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isRecording, setIsRecording] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const { toast } = useToast();

  const { showIntro, completeIntro } = useCharacterIntro('leonardo');

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(scrollToBottom, [messages]);

  const sendMessage = async () => {
    if (!inputMessage.trim() || isLoading) return;

    const userMessage: Message = {
      id: Date.now().toString(),
      sender: 'user',
      content: inputMessage,
      timestamp: new Date()
    };

    setMessages(prev => [...prev, userMessage]);
    setInputMessage('');
    setIsLoading(true);

    try {
      // Se c'è un sessionId, usa l'API del copilot, altrimenti usa Leonardo base
      const endpoint = sessionId ? '/api/copilot/message' : '/api/leonardo/chat';
      const body = sessionId 
        ? { sessionId, message: inputMessage }
        : { message: inputMessage, context, attachedFiles: [] };

      const response = await fetch(endpoint, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body)
      });

      if (!response.ok) {
        throw new Error('Failed to get response');
      }

      const data = await response.json();

      const leonardoMessage: Message = {
        id: (Date.now() + 1).toString(),
        sender: 'leonardo',
        content: data.response || "Mi dispiace, non sono riuscito a elaborare la tua richiesta.",
        timestamp: new Date()
      };

      setMessages(prev => [...prev, leonardoMessage]);

      // Se dovrebbe essere trasferito a un umano
      if (data.shouldTransferToHuman) {
        toast({
          title: "Trasferimento richiesto",
          description: "Leonardo suggerisce di trasferire questa conversazione a un operatore umano.",
          variant: "default"
        });
      }

    } catch (error) {
      console.error('Error sending message:', error);
      const errorMessage: Message = {
        id: (Date.now() + 2).toString(),
        sender: 'leonardo',
        content: 'Mi dispiace, c\'è stato un problema. Riprova tra poco.',
        timestamp: new Date()
      };
      setMessages(prev => [...prev, errorMessage]);

      toast({
        title: "Errore",
        description: "Impossibile inviare il messaggio. Riprova.",
        variant: "destructive"
      });
    } finally {
      setIsLoading(false);
    }
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      sendMessage();
    }
  };

  const handleVoiceInput = () => {
    if ('webkitSpeechRecognition' in window || 'SpeechRecognition' in window) {
      const SpeechRecognition = (window as any).webkitSpeechRecognition || (window as any).SpeechRecognition;
      const recognition = new SpeechRecognition();

      recognition.lang = 'it-IT';
      recognition.continuous = false;
      recognition.interimResults = false;

      recognition.onstart = () => {
        setIsRecording(true);
      };

      recognition.onresult = (event: any) => {
        const transcript = event.results[0][0].transcript;
        setInputMessage(prev => prev + transcript);
        setIsRecording(false);
      };

      recognition.onerror = () => {
        setIsRecording(false);
        toast({
          title: "Errore vocale",
          description: "Impossibile registrare l'audio. Controlla i permessi del microfono.",
          variant: "destructive"
        });
      };

      recognition.onend = () => {
        setIsRecording(false);
      };

      recognition.start();
    } else {
      toast({
        title: "Non supportato",
        description: "Il riconoscimento vocale non è supportato su questo browser.",
        variant: "destructive"
      });
    }
  };

  return (
    <div className="w-full h-[600px]">
      {showIntro && (
        <CharacterIntro
          character="leonardo"
          onComplete={completeIntro}
        />
      )}
      {!showIntro && (
        <Card className="w-full h-[600px] flex flex-col">
          <CardHeader className="border-b bg-blue-50">
            <CardTitle className="flex items-center gap-2 text-blue-600">
              <img 
                src="/attached_assets/leonardo foto profilo_1754851361956.png" 
                alt="Leonardo AI" 
                className="w-6 h-6"
              />
              Chat con Leonardo
          {sessionId && <span className="text-xs bg-blue-100 px-2 py-1 rounded">Copilot Attivo</span>}
        </CardTitle>
      </CardHeader>

      <CardContent className="flex-1 flex flex-col p-0">
        {/* Messages Area */}
        <div className="flex-1 overflow-y-auto p-4 space-y-4">
          {messages.length === 0 && (
            <div className="h-full flex flex-col items-center justify-center text-center text-slate-500 p-4">
              <div className="flex-1 flex items-center justify-center w-full max-h-64">
                <img 
                  src="/attached_assets/leonardo foto profilo_1754851361956.png" 
                  alt="Leonardo AI" 
                  className="max-w-full max-h-full object-contain"
                />
              </div>
              <div className="mt-4">
                <p className="font-semibold">Ciao! Sono Leonardo, il tuo assistente AI per vendite.</p>
                <p>Dimmi come posso aiutarti con la tua attività!</p>
              </div>
            </div>
          )}

          {messages.map((message) => (
            <div
              key={message.id}
              className={`flex items-start gap-3 ${
                message.sender === 'user' ? 'flex-row-reverse' : 'flex-row'
              }`}
            >
              <Avatar className="w-8 h-8">
                <AvatarFallback className={
                  message.sender === 'user' 
                    ? 'bg-green-100 text-green-600'
                    : 'bg-blue-100 text-blue-600'
                }>
                  {message.sender === 'user' ? (
                    <User className="w-4 h-4" />
                  ) : (
                    <img 
                      src="/attached_assets/leonardo foto profilo_1754851361956.png" 
                      alt="Leonardo AI" 
                      className="w-5 h-5 object-contain"
                    />
                  )}
                </AvatarFallback>
              </Avatar>

