                    <div className="grid grid-cols-2 gap-2">
                      <div>
                        <label className="text-xs text-slate-600">Materiale</label>
                        <input
                          type="text"
                          value={requestData.material || ''}
                          onChange={(e) => setRequestData(prev => ({ ...prev, material: e.target.value }))}
