// Funzione per trovare la scheda più appropriata
export function findBestProductSchema(userInput: string): ProductSchema | null {
  const input = userInput.toLowerCase();

  // Mappature intelligenti per riconoscimento prodotti
  const categoryMappings = {
    // Scarpe e calzature
    'scarpe': ['scarpe', 'sneakers', 'running', 'sportive', 'ginnastica', 'tennis', 'calcio', 'basket', 'spinning', 'cycling'],
    'abbigliamento': ['maglietta', 'camicia', 'felpa', 'pantaloni', 'jeans', 'giacca', 'vestito', 'gonna', 'maglione'],
    'smartphone': ['telefono', 'smartphone', 'cellulare', 'iphone', 'android'],
    'mobili': ['divano', 'tavolo', 'sedia', 'armadio', 'letto', 'scrivania', 'libreria', 'poltrona', 'mobile'],
    'elettrodomestici': ['frigorifero', 'lavatrice', 'lavastoviglie', 'forno', 'microonde', 'aspirapolvere']
  };

  // Trova la categoria più appropriata
  for (const [category, keywords] of Object.entries(categoryMappings)) {
    if (keywords.some(keyword => input.includes(keyword))) {
      // Trova la scheda specifica per quella categoria
      return productSchemas.find(schema => 
        schema.category === category || 
        schema.subcategory === category ||
        schema.name.toLowerCase().includes(category)
      ) || null;
    }
  }

  return null;
}

// Genera una nuova scheda prodotto per prodotti non riconosciuti
export async function generateDynamicProductSchema(userInput: string, aiModel: any): Promise<ProductSchema | null> {
  if (!aiModel) return null;

  const prompt = `Analizza questo prodotto richiesto dall'utente: "${userInput}"

Crea una scheda prodotto strutturata con questi campi appropriati per il prodotto:
- Budget (SOLO se è un prodotto commerciale con prezzo - non per servizi gratuiti, idee, software open source)
- Specifiche tecniche appropriate per il prodotto
- Condizioni (SOLO per prodotti fisici)

Rispondi SOLO con un JSON valido in questo formato:
{
  "category": "categoria_principale",
  "subcategory": "sottocategoria_opzionale", 
  "name": "Nome Descrittivo Prodotto",
  "description": "Breve descrizione del prodotto",
  "fields": [
    {
      "key": "budget",
      "label": "Budget",
      "type": "range", 
      "required": false,
      "placeholder": "Es: 50-200€"
    },
    {
      "key": "condition",
      "label": "Condizioni",
      "type": "select",
      "required": false,
      "options": ["nuovo", "usato", "ricondizionato", "indifferente"]
    }
    // Aggiungi altri campi specifici per questo prodotto
  ],
  "assistantInstructions": "Istruzioni specifiche per l'assistente per questo tipo di prodotto"
}

Mantieni la scheda concisa ma completa, massimo 6-7 campi totali.`;

  try {
    const result = await aiModel.generateContent(prompt);
    const responseText = result.response.text();

    // Estrai il JSON dalla risposta
    const jsonMatch = responseText.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      const schemaData = JSON.parse(jsonMatch[0]);
      console.log('🆕 Nuova scheda generata dinamicamente:', schemaData.name);
      return schemaData as ProductSchema;
    }
  } catch (error) {
    console.error('❌ Errore generazione scheda dinamica:', error);
  }

  return null;
}

// Funzione per generare domande intelligenti basate sulla scheda
export function generateSmartQuestion(schema: ProductSchema, collectedData: any): string | null {
  const missingRequired = schema.fields.filter(field => 
    field.required && !collectedData[field.key]
  );

  if (missingRequired.length > 0) {
    const field = missingRequired[0];
    return formatQuestionForField(field);
  }

  const missingOptional = schema.fields.filter(field => 
    !field.required && !collectedData[field.key]
  );

  if (missingOptional.length > 0) {
    const field = missingOptional[0];
    return formatQuestionForField(field);
  }

  return null; // Tutte le informazioni raccolte
}

function formatQuestionForField(field: ProductField): string {
  // Crea domande più naturali e conversazionali
  switch (field.key) {
    case 'budget':
      return "Hai un budget di riferimento in mente?";
    case 'condition':
      return "Preferisci nuovo o va bene anche usato?";
    case 'size':
      return "Che numero/taglia?";
    case 'type':
      return `Che tipo di ${field.label.toLowerCase()} stai cercando?`;
    case 'brand':
      return "Hai qualche marca in mente o va bene qualsiasi?";
    default:
      let question = `${field.label}?`;

      if (field.options && field.options.length > 0) {
        const examples = field.options.slice(0, 3).join(', ');
        question = `Per ${field.label.toLowerCase()}, hai preferenze? Ad esempio ${examples}.`;
      } else if (field.placeholder) {
        question += ` ${field.placeholder}`;
      }

      return question;
  }
}

// Funzione per validare e strutturare i dati raccolti
export function validateCollectedData(schema: ProductSchema, data: any): { isValid: boolean; missingFields: string[]; errors: string[] } {
  const missingFields: string[] = [];
  const errors: string[] = [];

  if (schema?.fields) {
    schema.fields.forEach(field => {
      if (field.required && !data[field.key]) {
        missingFields.push(field.label);
      }

    if (data[field.key] && field.validation) {
      const value = data[field.key];

      if (field.type === 'number') {
        const num = parseFloat(value);
        if (field.validation.min && num < field.validation.min) {
          errors.push(`${field.label} deve essere almeno ${field.validation.min}`);
        }
        if (field.validation.max && num > field.validation.max) {
          errors.push(`${field.label} deve essere al massimo ${field.validation.max}`);
        }
      }
    }
    });
  }

  return {
    isValid: missingFields.length === 0 && errors.length === 0,
    missingFields,
    errors
  };
}
